import {configSection,today,round} from '../core/business.js?v=20261101-v3a';
export function install(ctx){
 const receiptsFor=id=>(ctx.paymentReceipts||[]).filter(r=>r.quote_id===id);
 async function receiptListDialog(id){const q=ctx.quotes.find(q=>q.id===id);if(!q)return;const list=await ctx.rpc('list_payment_receipts',{p_quote:id});const d=ctx.modal('Recibos do pedido #'+q.number,`<p class="muted">Cada recibo preserva os dados e o valor da emissão. Estornos ficam indicados no documento.</p>${list.length?list.map(r=>`<div class="history-row"><div><strong>REC-${String(r.number).padStart(6,'0')} · ${ctx.money(r.amount)}</strong><p>${ctx.date(r.created_at)} · ${r.reversed?'Recebimento estornado':'Emitido'}</p></div><button class="secondary small" data-open-receipt="${r.id}">Abrir / PDF</button></div>`).join(''):ctx.empty('Nenhum recibo emitido.','O recibo pode ser preparado ao iniciar a produção ou a partir de um recebimento registrado.')}<div class="form-actions">${ctx.can('receipts','create')&&!['cancelled','suspended'].includes(q.stage)?'<button class="primary" id="new-receipt">Preparar recibo</button>':''}<button type="button" class="secondary" data-close>Fechar</button></div>`,{wide:true});d.querySelectorAll('[data-open-receipt]').forEach(el=>el.onclick=()=>{d.close();showReceipt(el.dataset.openReceipt)});d.querySelector('#new-receipt')?.addEventListener('click',()=>{d.close();productionReceiptDialog(id)})}
 function productionReceiptDialog(id,transition=null){const q=ctx.quotes.find(q=>q.id===id);if(!q)return;const cfg=configSection(ctx.settings,'budget'),prod=configSection(ctx.settings,'production'),list=receiptsFor(id),valid=list.filter(r=>!r.reversed),paid=Number(ctx.orderFinance?.find(x=>x.quote_id===id)?.paid||0),issued=round(valid.reduce((n,r)=>n+Number(r.amount),0)),available=round(Math.max(0,paid-issued)),deposit=Number(q.production?.agreed_entry_amount??round(Number(q.total)*Number(q.entry_percentage)/100)),canRecord=!!transition&&ctx.can('finance','create')&&ctx.can('finance','settle'),request=crypto.randomUUID();const amount=available||deposit;
  const d=ctx.modal(transition?'Adiantamento e início da produção':'Preparar recibo de pagamento',`<form id="receipt-form"><p><strong>Pedido #${q.number} · ${ctx.esc(q.client_snapshot.name)}</strong></p><div class="receipt-balances"><span>Pedido <strong>${ctx.money(q.total)}</strong></span><span>Recebido <strong>${ctx.money(paid)}</strong></span><span>Já em recibos <strong>${ctx.money(issued)}</strong></span></div>${valid.length&&transition?`<p class="note">Já existe recibo deste pedido. Você pode continuar com o documento emitido.</p><button type="button" class="secondary" id="use-issued-receipt">Iniciar produção e abrir REC-${String(valid[0].number).padStart(6,'0')}</button>`:''}${transition&&ctx.can('finance','edit')&&!valid.length?`<label class="check-row"><input type="checkbox" name="adjust_deposit">Ajustar o adiantamento acordado para o valor deste recibo e recalcular o saldo</label><p class="muted helper">Entrada atual: ${ctx.money(deposit)}. A proposta anterior fica no histórico; o recibo registra a condição ajustada.</p>`:''}<div class="grid2">${ctx.field('Valor a constar no recibo (R$)','amount','number',amount||'','required min="0.01" max="'+q.total+'" step="0.01"')}<div class="field">Recebido e ainda sem recibo<strong>${ctx.money(available)}</strong><small>O valor pode ser ajustado antes da emissão.</small></div></div>${canRecord?`<label class="check-row"><input type="checkbox" name="record_payment" ${amount>available?'checked':''}>Registrar no financeiro a diferença ainda não recebida</label><div id="receipt-payment-fields">${ctx.business?.accounts?.some(a=>a.active)?'':'<p class="error">Cadastre ou ative uma conta em Configurações → Financeiro e extratos para registrar o recebimento.</p>'}<div class="grid2"><label class="field">Conta que recebeu<select name="account">${ctx.accountsOptions()}</select></label>${ctx.field('Data do recebimento','paid_on','date',today(),'required')}<label class="field">Forma de pagamento<select name="method">${configSection(ctx.settings,'finance').payment_methods.map(m=>`<option>${ctx.esc(m)}</option>`).join('')}</select></label></div><p class="note" id="receipt-additional"></p><label class="check-row"><input type="checkbox" name="payment_confirmed">Confirmo que esse valor já foi recebido. Este registro não movimenta dinheiro no banco.</label></div>`:`<p class="note">${transition?'Para registrar uma entrada, é necessário acesso a criar lançamentos e registrar baixas. ':''}O recibo confirma valores já recebidos e ainda não documentados.</p>`}<label class="field">Mensagem ao cliente · vai para o PDF<textarea name="message" maxlength="5000">${ctx.esc(cfg.receipt_message)}</textarea></label><p class="note">A emissão preserva o valor, o texto e os dados desta confirmação. Os preços do orçamento continuam como foram emitidos.</p><p class="error" id="receipt-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button>${transition&&(!prod.require_deposit||deposit===0)?'<button class="secondary" type="button" id="start-without-receipt">Iniciar sem recibo</button>':''}<button class="primary" type="submit">${transition?'Confirmar produção e preparar PDF':'Emitir e abrir recibo'}</button></div></form>`,{wide:true});const form=d.querySelector('form');
  function update(){if(!canRecord)return;const extra=round(Math.max(0,issued+Number(form.elements.amount.value||0)-paid)),record=form.elements.record_payment.checked&&extra>0;d.querySelector('#receipt-payment-fields').hidden=!record;for(const key of ['account','paid_on','method','payment_confirmed']){form.elements[key].disabled=!record;form.elements[key].required=record}d.querySelector('#receipt-additional').textContent='Será registrada uma baixa de '+ctx.money(extra)+'. As parcelas da entrada e do saldo serão utilizadas sem duplicação.';}
  form.elements.amount.oninput=update;if(canRecord)form.elements.record_payment.onchange=update;update();
  async function moveAndOpen(receiptId){await ctx.rpc('update_order',transition);await ctx.load();d.close();if(receiptId)await showReceipt(receiptId);else ctx.render('workflow')}
  d.querySelector('#use-issued-receipt')?.addEventListener('click',async e=>{e.target.disabled=true;try{await moveAndOpen(valid[0].id)}catch(err){d.querySelector('#receipt-error').textContent=err.message;e.target.disabled=false}});
  d.querySelector('#start-without-receipt')?.addEventListener('click',async e=>{e.target.disabled=true;try{await moveAndOpen()}catch(err){d.querySelector('#receipt-error').textContent=err.message;e.target.disabled=false}});
  form.onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const fd=new FormData(form),record=canRecord&&fd.has('record_payment')&&issued+Number(fd.get('amount'))>paid;if(record&&!fd.has('payment_confirmed'))throw Error('Confirme que o recebimento já ocorreu.');if(record&&!fd.get('account'))throw Error('Cadastre ou ative uma conta em Configurações → Financeiro antes de registrar a entrada.');const receipt=transition?await ctx.rpc('start_order_with_receipt',{...transition,p_amount:Number(fd.get('amount')),p_record_payment:record,p_adjust_deposit:fd.has('adjust_deposit'),p_account:record?fd.get('account'):null,p_paid_on:record?fd.get('paid_on'):null,p_method:record?fd.get('method'):'',p_message:fd.get('message'),p_request:request}):await ctx.rpc('issue_payment_receipt',{p_quote:id,p_amount:Number(fd.get('amount')),p_message:fd.get('message'),p_request:request});await ctx.load();d.close();await showReceipt(receipt);ctx.toast('Recibo emitido com os dados confirmados.')}catch(err){d.querySelector('#receipt-error').textContent=err.message;e.submitter.disabled=false}};
 }
 async function showReceipt(id){try{ctx.receiptData=await ctx.rpc('receipt_view_data',{p_receipt:id});ctx.render('receipt')}catch(e){ctx.toast(e.message)}}
 function receiptView(){const data=ctx.receiptData;if(!data)return ctx.render('quotes');const r=data.receipt,s=r.snapshot,c=s.company||{},client=s.client||{};ctx.shell(`${ctx.head('Recibo REC-'+String(r.number).padStart(6,'0'),'Confirmação de recebimento vinculada ao pedido #'+s.quote_number+'.')}<div class="form-actions"><button class="secondary" id="receipt-back">Voltar ao pedido</button>${ctx.can('receipts','print')?'<button class="primary" id="receipt-print">Imprimir / Salvar PDF</button>':''}</div><article class="quote-print receipt-print">${data.reversed?'<div class="quote-status-note">RECEBIMENTO ESTORNADO · Documento mantido apenas para histórico.</div>':['cancelled','suspended'].includes(data.current_stage)?'<div class="quote-status-note">O pedido está atualmente cancelado ou suspenso. Esta confirmação registra o recebimento da data de emissão.</div>':''}<header><div>${s.show_logo?`<div class="brand ${c.logo?'custom-brand':'document-brand'}"><img src="${ctx.esc(c.logo||'logo-document.png')}" alt="${ctx.esc(c.company||'Avelon Têxtil')}"></div>`:''}<p>${ctx.esc(c.company||'Avelon Têxtil')}<br>${ctx.esc(c.contact)}</p></div><div><h1>${ctx.esc(s.title||'Recibo de adiantamento')}</h1><p><strong>REC-${String(r.number).padStart(6,'0')}</strong><br>Emissão: ${ctx.date(r.created_at)}<br>Pedido / orçamento: #${String(s.quote_number).padStart(4,'0')}</p></div></header><div class="receipt-value"><span>Valor confirmado neste recibo</span><strong>${ctx.money(r.amount)}</strong></div><p>Recebemos de <strong>${ctx.esc(client.name)}</strong>${client.document?' · '+ctx.esc(client.document):''} o valor de <strong>${ctx.money(r.amount)}</strong>, referente ao pagamento do pedido identificado neste documento.</p><section class="receipt-message"><h2>Seu pedido está em boas mãos.</h2><p>${ctx.esc(s.message)}</p></section><div class="receipt-status-grid"><div><span>Etapa na emissão</span><strong>${ctx.esc(s.stage)}</strong></div><div><span>Personalização</span><strong>${ctx.esc(s.technique||'Conforme orçamento')}</strong></div><div><span>Entrega prevista</span><strong>${s.delivery_date?ctx.date(s.delivery_date):'Conforme orçamento'}</strong></div></div><h3>Resumo do pedido</h3><div class="table-wrap"><table><thead><tr><th>Item / personalização</th><th>Quantidade</th></tr></thead><tbody>${(s.items||[]).map(it=>`<tr><td><strong>${ctx.esc(it.description)}</strong><div class="details">${ctx.esc(it.details)}</div></td><td>${it.quantity}</td></tr>`).join('')}</tbody></table></div><div class="receipt-totals">${s.agreed_entry_amount!=null?`<p>Adiantamento acordado nesta confirmação <strong>${ctx.money(s.agreed_entry_amount)}</strong></p>`:''}<p>Total do pedido <strong>${ctx.money(s.quote_total)}</strong></p><p>Recebido acumulado na emissão <strong>${ctx.money(s.received_total)}</strong></p><p>Saldo a receber na emissão <strong>${ctx.money(s.remaining)}</strong></p></div>${s.show_signature&&c.signature?`<div class="document-signature"><img src="${ctx.esc(c.signature)}" class="${c.signature_invert?'invert-signature':''}" alt="Assinatura de ${ctx.esc(c.signature_name)}"><p>${ctx.esc(c.signature_name)}<br>${c.city?ctx.esc(c.city)+', ':''}${ctx.date(r.created_at)}</p></div>`:''}<p class="muted">Avelon Têxtil · Cuidado em cada etapa, qualidade em cada entrega.</p></article>`);ctx.$('#receipt-back').onclick=()=>ctx.can('quotes')?ctx.openQuote(r.quote_id):ctx.render('workflow');ctx.$('#receipt-print')?.addEventListener('click',async()=>{try{await ctx.rpc('receipt_print_data',{p_receipt:r.id});window.print()}catch(e){ctx.toast(e.message)}})}
 Object.assign(ctx,{receiptListDialog,productionReceiptDialog,showReceipt,receiptView});
}
